import React from "react";
import { Composition } from "remotion";
import { VIDEOS } from "./videos.generated";
import { WithCaptions } from "./engine/WithCaptions";

// One composition per videos/<id>/ folder (registry generated by `npm run gen`), id "oj-<id>", 1080x1920 at 30 fps.
// Every video is wrapped in the one-word captions (`{"captions": false}` input prop turns them off).
const ENTRIES = VIDEOS.map((v) => {
  const Video = v.Component;
  const Wrapped: React.FC = () => (
    <WithCaptions words={v.words}>
      <Video />
    </WithCaptions>
  );
  return { id: v.id, frames: v.frames, Wrapped };
});

export const RemotionRoot: React.FC = () => (
  <>
    {ENTRIES.map((e) => (
      <Composition key={e.id} id={"oj-" + e.id} component={e.Wrapped} durationInFrames={e.frames} fps={30} width={1080} height={1920} />
    ))}
  </>
);
